// Google広告透明性センターのHTMLを解析してデータを抽出
const input = $input.all();
const results = [];

input.forEach((item, index) => {
  const html = item.json.data || '';
  const competitorName = $node['競合企業リスト取得'].json[index]?.company_name || 'Unknown';

  // 簡易的なHTMLパース（実際のスクレイピングではより複雑な処理が必要）
  const adPattern = /<div[^>]*class="[^"]*ad-item[^"]*"[^>]*>(.*?)<\/div>/gs;
  const titlePattern = /<h[23][^>]*>(.*?)<\/h[23]>/g;
  const descPattern = /<p[^>]*class="[^"]*description[^"]*"[^>]*>(.*?)<\/p>/g;

  let adMatches = html.match(adPattern) || [];

  adMatches.forEach((adHtml, adIndex) => {
    const titleMatch = titlePattern.exec(adHtml);
    const descMatch = descPattern.exec(adHtml);

    if (titleMatch || descMatch) {
      results.push({
        competitor_name: competitorName,
        ad_id: `${competitorName}_${Date.now()}_${adIndex}`,
        ad_title: titleMatch ? titleMatch[1].replace(/<[^>]*>/g, '') : '',
        ad_description: descMatch ? descMatch[1].replace(/<[^>]*>/g, '') : '',
        ad_format: 'display',
        display_url: item.json.url || '',
        final_url: item.json.url || '',
        last_seen_date: new Date().toISOString().split('T')[0],
        first_seen_date: new Date().toISOString().split('T')[0],
        geo_targets: ['Japan'],
        devices: ['desktop', 'mobile']
      });
    }
  });

  // データが見つからない場合のダミーデータ（テスト用）
  if (results.length === 0) {
    results.push({
      competitor_name: competitorName,
      ad_id: `${competitorName}_${Date.now()}_sample`,
      ad_title: `${competitorName}のサンプル広告タイトル`,
      ad_description: `${competitorName}のサンプル広告説明文です。`,
      ad_format: 'display',
      display_url: item.json.url || '',
      final_url: item.json.url || '',
      last_seen_date: new Date().toISOString().split('T')[0],
      first_seen_date: new Date().toISOString().split('T')[0],
      geo_targets: ['Japan'],
      devices: ['desktop', 'mobile']
    });
  }
});

return results.map(item => ({ json: item }));

