const crypto = require('crypto');

// 入力データの取得
const items = $input.all();
const results = [];

items.forEach(item => {
  const rawData = item.json;
  let analysisResult = {};

  try {
    // OpenAIからの応答を解析
    const aiResponse = rawData.choices?.[0]?.message?.content || '{}';
    analysisResult = JSON.parse(aiResponse);
  } catch (error) {
    console.error('AI分析結果の解析エラー:', error);
    // デフォルト値を設定
    analysisResult = {
      appeal_points: {
        price: false,
        quality: false,
        convenience: false,
        emotion: false,
        scarcity: false
      },
      message_clarity_score: 3,
      usp_strength_score: 3,
      cta_effectiveness_score: 3,
      target_fit_score: 3,
      swot: {
        strengths: '分析エラー',
        weaknesses: '分析エラー',
        opportunities: '分析エラー',
        threats: '分析エラー'
      }
    };
  }

  // データ整形
  const formattedData = {
    record_id: crypto.randomUUID(),
    competitor_name: rawData.competitor_name || 'Unknown',
    ad_id: rawData.ad_id || `AD_${Date.now()}`,
    ad_title: rawData.ad_title || '',
    ad_description: rawData.ad_description || '',
    ad_format: rawData.ad_format || 'unknown',
    display_url: rawData.display_url || '',
    final_url: rawData.final_url || '',
    last_seen_date: rawData.last_seen_date || new Date().toISOString().split('T')[0],
    first_seen_date: rawData.first_seen_date || new Date().toISOString().split('T')[0],
    geo_targets: JSON.stringify(rawData.geo_targets || []),
    devices: JSON.stringify(rawData.devices || []),

    // AI分析結果
    appeal_points: JSON.stringify(analysisResult.appeal_points || {}),
    message_clarity_score: analysisResult.message_clarity_score || 0,
    usp_strength_score: analysisResult.usp_strength_score || 0,
    cta_effectiveness_score: analysisResult.cta_effectiveness_score || 0,
    target_fit_score: analysisResult.target_fit_score || 0,
    overall_score: Math.round(((analysisResult.message_clarity_score || 0) + 
                              (analysisResult.usp_strength_score || 0) + 
                              (analysisResult.cta_effectiveness_score || 0) + 
                              (analysisResult.target_fit_score || 0)) / 4 * 10) / 10,

    // SWOT分析
    strengths: analysisResult.swot?.strengths || '',
    weaknesses: analysisResult.swot?.weaknesses || '',
    opportunities: analysisResult.swot?.opportunities || '',
    threats: analysisResult.swot?.threats || '',

    // システム項目
    update_count: 1,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  results.push(formattedData);
});

return results.map(item => ({ json: item }));

