// 実行サマリーの生成
const items = $input.all();
const totalAds = items.length;
const highScoreAds = items.filter(item => (item.json.overall_score || 0) >= 4).length;
const competitors = [...new Set(items.map(item => item.json.competitor_name))];
const averageScore = items.reduce((sum, item) => sum + (item.json.overall_score || 0), 0) / totalAds;

const summary = {
  execution_id: $executionId,
  timestamp: new Date().toISOString(),
  total_ads_processed: totalAds,
  high_score_ads: highScoreAds,
  unique_competitors: competitors.length,
  competitor_list: competitors,
  average_overall_score: Math.round(averageScore * 100) / 100,
  status: 'completed'
};

console.log('ワークフロー実行サマリー:', JSON.stringify(summary, null, 2));

return {
  json: summary
};
